      <header className=\"topbar\"><div className=\"breadcrumbs\"><span>Рабочее пространство</span><Icon name=\"chevron\" size={13}/><strong>Клиенты</strong></div><div className=\"topbar-right\"><span className=\"live-dot\"/>Все изменения сохранены<div className=\"topbar-divider\"/><div className=\"notification-wrap\" onClick={e=>e.stopPropagation()}><button className=\"icon-button notification-button\" aria-label=\"Уведомления\" aria-expanded={popover==='notifications'} onClick={()=>togglePopover('notifications')}><Icon name=\"bell\" size={19}/><i/></button>{popover==='notifications'&&<div className=\"dropdown notification-menu\"><h3>Уведомления</h3><div className=\"notification-item\"><span className=\"notification-icon\"><Icon name=\"check\"/></span><div><strong>Вы готовы к работе</strong><p>Клиентская база загружена. Добавляйте клиентов и следите за их активностью.</p><small>Только что</small></div></div></div>}</div><button className=\"small-avatar\" onClick={()=>setModal('profile')} aria-label=\"Открыть профиль\">АС</button></div></header>
      <main>
        <div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ БИЗНЕС В ДЕТАЛЯХ</div><h1>Клиенты <span>{clients.length}</span></h1><p>Управляйте клиентами и развивайте отношения с ними.</p></div><Button className=\"primary-button\" size=\"l\" onClick={()=>setModal('add')}><Icon name=\"plus\" size={17}/>Добавить клиента</Button></div>
        <section className=\"metrics\" aria-label=\"Статистика клиентов\">
          <div className=\"metric-card\"><div className=\"metric-top\"><span>Всего клиентов</span><Icon name=\"users\" size={17}/></div><div className=\"metric-number\">{clients.length}<Sparkline/></div><div className=\"metric-foot\"><span className=\"growth\">↗ 12,3%</span><span>по сравнению с прошлым месяцем</span></div></div>
          <div className=\"metric-card\"><div className=\"metric-top\"><span>Активные клиенты</span><span className=\"metric-status-dot\"/></div><div className=\"metric-number\">{counts.active}<Sparkline variant={1}/></div><div className=\"metric-foot\"><span className=\"growth\">↗ 8,6%</span><span>по сравнению с прошлым месяцем</span></div></div>
          <div className=\"metric-card\"><div className=\"metric-top\"><span>Общая выручка</span><span className=\"ruble-icon\">₽</span></div><div className=\"metric-number\">{(totalRevenue/1000000).toLocaleString('ru-RU',{maximumFractionDigits:2})} <span className=\"metric-unit\">млн ₽</span><Sparkline variant={2}/></div><div className=\"metric-foot\"><span className=\"growth\">↗ 16,2%</span><span>по сравнению с прошлым месяцем</span></div></div>
        </section>

        <section className=\"data-card\" aria-label=\"Клиентская база\">
          <div className=\"table-top\"><div><h2>Клиентская база</h2><p>Все ваши клиенты в одном месте.</p></div><Button view=\"outlined\" size=\"l\" className=\"export-button\" onClick={()=>exportCsv()}><Icon name=\"download\" size={16}/>Экспорт<Icon name=\"chevron\" size={12} className=\"down-chevron\"/></Button></div>
          <div className=\"tabs\" role=\"tablist\" aria-label=\"Статус клиентов\">{([['all','Все клиенты'],['active','Активные'],['new','Новые'],['archived','В архиве']] as const).map(([id,label])=><button key={id} role=\"tab\" aria-selected={tab===id} className={tab===id?'selected':''} onClick={()=>setTab(id)}>{label}<span>{counts[id]}</span></button>)}</div>
          <div className=\"table-toolbar\"><div className=\"search-field\"><Icon name=\"search\" size={17}/><input aria-label=\"Поиск клиентов\" placeholder=\"Поиск по имени, почте или компании...\" value={query} onChange={e=>setQuery(e.target.value)}/>{query?<button className=\"icon-button clear-search\" aria-label=\"Очистить поиск\" onClick={()=>setQuery('')}><Icon name=\"close\" size={14}/></button>:<span className=\"search-hint\">⌕</span>}</div><div className=\"toolbar-actions\" onClick={e=>e.stopPropagation()}><div className=\"popover-anchor\"><button className={"'`control-button ${plan!=='"'all'?'is-filtered':''}"'`} onClick={()=>togglePopover('"'filter')} aria-expanded={popover==='filter'}><Icon name=\"filter\" size={17}/>Фильтры{plan"'!=='"'all'&&<span className=\"filter-count\">1</span>}</button>{popover==='filter'&&<div className=\"dropdown filter-menu\"><h3>Фильтры</h3><label htmlFor=\"plan-filter\">Тариф клиента</label><select id=\"plan-filter\" value={plan} onChange={e=>setPlan(e.target.value)}><option value=\"all\">Все тарифы</option>{['Базовый','Про','Бизнес'].map(v=><option key={v}>{v}</option>)}</select><button className=\"reset-filter\" onClick={()=>{setPlan('all');setQuery('');setTab('all');}}>Сбросить фильтры</button></div>}</div><div className=\"popover-anchor\"><button className=\"control-button\" onClick={()=>togglePopover('columns')} aria-expanded={popover==='columns'}><Icon name=\"columns\" size={16}/><span>Столбцы</span></button>{popover==='columns'&&<div className=\"dropdown columns-menu\"><h3>Столбцы таблицы</h3>{(Object.keys(columnLabels) as SortKey[]).map(key=><Checkbox key={key} checked={columns.includes(key)} disabled={key==='name'} onUpdate={checked=>setColumns(prev=>checked?[...prev,key]:prev.filter(c=>c"'!==key))}>{columnLabels[key]}</Checkbox>)}</div>}</div></div></div>
          {selected.size>0&&<div className="selection-toolbar"><div><span className="selected-icon"><Icon name="check" size={13}/></span>Выбрано: <strong>{selected.size}</strong><button onClick={()=>setSelected(new Set())}>Снять выделение</button></div><button onClick={()=>updateStatus(selected,'"'archived')}><Icon name=\"archive\" size={15}/>В архив</button></div>}
          <div className=\"table-scroll\"><table className={compact?'compact':''}><thead><tr><th className=\"checkbox-cell\"><Checkbox checked={allChecked} indeterminate={"'!allChecked&&someChecked} onUpdate={toggleAll} aria-label="Выбрать все строки на странице"/></th>{(Object.keys(columnLabels) as SortKey[]).filter(key=>columns.includes(key)).map(key=><th key={key} className={`column-${key}`} aria-sort={sort.key===key?(sort.direction==='"'asc'?'ascending':'descending'):'none'}><button onClick={()=>{setSort(prev=>({key,direction:prev.key===key&&prev.direction==='asc'?'desc':'asc'}));setPage(1);}}>{columnLabels[key]}{sort.key===key?<span className=\"active-sort\">{sort.direction==='asc'?'↑':'↓'}</span>:<Icon name=\"arrow\" size={13}/>}</button></th>)}<th className=\"row-action\"><span className=\"sr-only\">Действия</span></th></tr></thead><tbody>{visible.map(client=><tr key={client.id} className={selected.has(client.id)?'row-selected':''}><td className=\"checkbox-cell\"><Checkbox checked={selected.has(client.id)} onUpdate={()=>toggleSelected(client.id)} aria-label={"'`Выбрать: ${client.name}`}/></td>{columns.includes('"'name')&&<td className=\"name-cell\"><button className=\"client-button\" onClick={()=>setDetail(client)}><span className={"'`client-avatar avatar-${client.color}`}>{initials(client.name)}</span><span><strong>{client.name}</strong><small>{client.email}</small></span></button></td>}{columns.includes('"'company')&&<td className=\"company-cell\">{client.company}</td>}{columns.includes('status')&&<td><span className={"'`status-badge status-${client.status}`}><i/>{statuses[client.status]}</span></td>}{columns.includes('"'plan')&&<td><span className={"'`plan-badge plan-${client.plan==='"'Бизнес'?'business':client.plan==='Про'?'pro':'basic'}"'`}>{client.plan}</span></td>}{columns.includes('"'revenue')&&<td className=\"revenue-cell\">{money(client.revenue)}</td>}{columns.includes('date')&&<td className=\"date-cell\">{dateLabel(client.date)}</td>}<td className=\"row-action\"><button className=\"icon-button row-menu\" aria-label={"'`Действия: ${client.name}`} onClick={()=>setDetail(client)}><Icon name="more" size={19}/></button></td></tr>)}</tbody></table>{visible.length===0&&<div className="empty-state"><span><Icon name="search" size={27}/></span><h3>Клиенты не найдены</h3><p>Попробуйте другой запрос или измените фильтры.</p><Button view="outlined" onClick={()=>{setQuery('"'');setPlan('all');setTab('all');}}>Сбросить фильтры</Button></div>}</div>
          <div className=\"table-footer\"><span className=\"result-count\">Показано <strong>{filtered.length?(currentPage-1)*pageSize+1:0}–{Math.min(currentPage*pageSize,filtered.length)}</strong> из <strong>{filtered.length}</strong> клиентов</span><div className=\"pagination\"><button className=\"page-arrow\" disabled={currentPage===1} onClick={()=>setPage(currentPage-1)} aria-label=\"Предыдущая страница\"><Icon name=\"chevron\" size={14} className=\"previous-chevron\"/></button>{pageNumbers.map((n,i)=>typeof n==='number'?<button key={i} className={"'`page-button ${n===currentPage?'"'current':''}"'`} aria-label={`Страница ${n}`} aria-current={n===currentPage?'"'page':undefined} onClick={()=>setPage(n)}>{n}</button>:<span key={i} className=\"page-ellipsis\">{n}</span>)}<button className=\"page-arrow\" disabled={currentPage===pageCount} onClick={()=>setPage(currentPage+1)} aria-label=\"Следующая страница\"><Icon name=\"chevron\" size={14}/></button></div><label className=\"page-size\">На странице<select value={pageSize} onChange={e=>setPageSize(Number(e.target.value))} aria-label=\"Количество строк на странице\">{[8,16,32].map(n=><option key={n} value={n}>{n}</option>)}</select></label></div>
        </section>
        <div className=\"page-bottom\"><span><span className=\"keyboard-key\">↵</span> Нажмите на имя клиента, чтобы открыть его карточку</span><span>Сделано для вашего роста <span className=\"footer-flower\">✳</span></span></div>
      </main>
      <footer className=\"app-footer\"><span>© 2026 Folio</span><span>Порядок в данных. Фокус на главном.</span><span className=\"system-status\"><i/>Все системы работают</span></footer>
    </div>

    <Modal open={modal"'!==null} onOpenChange={open=>{if(!open)setModal(null);}} contentClassName="app-modal" aria-label={modal==='"'add'?'Добавить клиента':modal==='help'?'Помощь и поддержка':'Информация'}><div className=\"modal-heading\"><div><span className=\"eyebrow\">FOLIO WORKSPACE</span><h2>{({add:'Новый клиент',help:'Помощь и поддержка',overview:'Обзор пространства',reports:'Отчёты',settings:'Настройки пространства',profile:'Ваш профиль'} as Record<string,string>)[modal??'add']}</h2></div><button className=\"icon-button\" onClick={()=>setModal(null)} aria-label=\"Закрыть окно\"><Icon name=\"close\" size={20}/></button></div>
      {modal==='add'&&<form onSubmit={addClient} className=\"client-form\"><p>Добавьте контакт — и начните новую историю сотрудничества.</p><label>Имя и фамилия<input required autoFocus maxLength={80} placeholder=\"Например, Анна Иванова\" value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} pattern=\".*\\S.*\"/></label><label>Электронная почта<input type=\"email\" required placeholder=\"name@company.ru\" value={draft.email} onChange={e=>setDraft({...draft,email:e.target.value})}/></label><div className=\"form-row\"><label>Компания<input required maxLength={80} placeholder=\"Название компании\" value={draft.company} onChange={e=>setDraft({...draft,company:e.target.value})} pattern=\".*\\S.*\"/></label><label>Тариф<select value={draft.plan} onChange={e=>setDraft({...draft,plan:e.target.value})}>{['Базовый','Про','Бизнес'].map(p=><option key={p}>{p}</option>)}</select></label></div><div className=\"modal-footer\"><Button size=\"l\" view=\"outlined\" onClick={()=>setModal(null)}>Отмена</Button><Button size=\"l\" className=\"primary-button\" type=\"submit\"><Icon name=\"plus\" size={16}/>Добавить клиента</Button></div></form>}
      {modal==='help'&&<div className=\"modal-body help-content\"><p>Небольшой гид по вашей клиентской базе.</p><h3>Сортировка и поиск</h3><p>Нажмите на заголовок столбца, чтобы изменить порядок. Повторное нажатие меняет направление сортировки. Поиск работает по имени, почте и компании.</p><h3>Работа с несколькими клиентами</h3><p>Отмечайте клиентов чекбоксами. Чекбокс в шапке выбирает всю текущую страницу. Выбор сохраняется при переходе на другие страницы.</p><h3>Экспорт данных</h3><p>Кнопка «Экспорт» скачивает CSV с выбранными клиентами. Если никто не выбран, экспортируются все клиенты с учётом фильтров.</p></div>}
      {modal==='overview'&&<div className=\"modal-body\"><p>Ваш бизнес в цифрах на сегодня.</p><div className=\"overview-grid\"><div><small>Всего клиентов</small><strong>{counts.all}</strong></div><div><small>Активные</small><strong>{counts.active}</strong></div><div><small>Новые</small><strong>{counts.new}</strong></div><div><small>В архиве</small><strong>{counts.archived}</strong></div></div><div className=\"overview-revenue\">Общая выручка <strong>{money(totalRevenue)}</strong></div><Button className=\"primary-button\" size=\"l\" width=\"max\" onClick={()=>setModal(null)}>Перейти к клиентам</Button></div>}
      {modal==='reports'&&<div className=\"modal-body\"><p>Скачайте актуальные данные для анализа вашего бизнеса.</p>{['Базовый','Про','Бизнес'].map(p=><div className=\"report-row\" key={p}><span><strong>{p}</strong><small>{clients.filter(c=>c.plan===p).length} клиентов</small></span><strong>{money(clients.filter(c=>c.plan===p).reduce((a,c)=>a+c.revenue,0))}</strong><button className=\"icon-button\" aria-label={"'`Экспорт клиентов тарифа ${p}`} onClick={()=>exportCsv(clients.filter(c=>c.plan===p))}><Icon name="download"/></button></div>)}<Button className="primary-button" width="max" size="l" onClick={()=>exportCsv(clients)}><Icon name="download" size={16}/>Скачать полный отчёт</Button></div>}
      {modal==='"'settings'&&<div className=\"modal-body\"><div className=\"setting-row\"><div><strong>Компактная таблица</strong><p>Уменьшить высоту строк в клиентской базе</p></div><Checkbox checked={compact} onUpdate={setCompact} aria-label=\"Компактная таблица\"/></div><h3>Ваш тариф</h3><div className=\"current-plan\"><span className=\"plan-badge plan-pro\">Про</span><strong>Всё для работы с клиентами</strong><p>Неограниченная база клиентов, фильтры и экспорт данных включены в ваше пространство.</p></div><Button size=\"l\" className=\"primary-button\" onClick={()=>setModal(null)} width=\"max\">Готово</Button></div>}
      {modal==='profile'&&<div className=\"modal-body\"><div className=\"profile-detail\"><span className=\"profile-avatar\">АС</span><h3>Алексей Соколов</h3><p>alexey@folio.ru</p><span className=\"plan-badge plan-pro\">Администратор</span></div><div className=\"overview-revenue\">Рабочее пространство<strong>{workspace}</strong></div><p className=\"profile-note\">Вы управляете клиентами и настройками этого пространства.</p></div>}
    </Modal>
    <Modal open={detail"'!==null} onOpenChange={open=>{if(!open)setDetail(null);}} contentClassName="app-modal" aria-label="Карточка клиента">{detail&&<><div className="modal-heading"><div><span className="eyebrow">КАРТОЧКА КЛИЕНТА</span><h2>{detail.name}</h2></div><button className="icon-button" onClick={()=>setDetail(null)} aria-label="Закрыть карточку"><Icon name="close" size={20}/></button></div><div className="modal-body"><div className="client-detail-top"><span className={`client-avatar avatar-${detail.color}`}>{initials(detail.name)}</span><span className={`status-badge status-${detail.status}`}><i/>{statuses[detail.status]}</span></div><dl className="detail-list"><div><dt>Электронная почта</dt><dd>{detail.email}</dd></div><div><dt>Компания</dt><dd>{detail.company}</dd></div><div><dt>Тариф</dt><dd>{detail.plan}</dd></div><div><dt>Выручка</dt><dd>{money(detail.revenue)}</dd></div><div><dt>Дата добавления</dt><dd>{dateLabel(detail.date)}</dd></div></dl><div className="detail-actions"><Button size="l" view="outlined" onClick={()=>exportCsv([detail])}><Icon name="download" size={16}/>Экспорт</Button><Button size="l" className="primary-button" onClick={()=>updateStatus(new Set([detail.id]),detail.status==='"'archived'?'active':'archived')}><Icon name={detail.status==='archived'?'check':'archive'} size={16}/>{detail.status==='archived'?'Восстановить':'В архив'}</Button></div></div></>}</Modal>
    {toast&&<div className=\"toast\" role=\"status\"><span><Icon name=\"check\" size={16}/></span>{toast}<button onClick={()=>setToast('')} aria-label=\"Скрыть уведомление\"><Icon name=\"close\" size={15}/></button></div>}
  </div>;
}
EOF
