      {modal==='profile'&&<div className=\"modal-body\"><div className=\"profile-detail\"><span className=\"profile-avatar\">АС</span><h3>Алексей Соколов</h3><p>alexey@folio.ru</p><span className=\"plan-badge plan-pro\">Администратор</span></div><div className=\"overview-revenue\">Рабочее пространство<strong>{workspace}</strong></div><p className=\"profile-note\">Вы управляете клиентами и настройками этого пространства.</p></div>}
    </Modal>
    <Modal open={detail"'!==null} onOpenChange={open=>{if(!open)setDetail(null);}} contentClassName="app-modal" aria-label="Карточка клиента">{detail&&<><div className="modal-heading"><div><span className="eyebrow">КАРТОЧКА КЛИЕНТА</span><h2>{detail.name}</h2></div><button className="icon-button" onClick={()=>setDetail(null)} aria-label="Закрыть карточку"><Icon name="close" size={20}/></button></div><div className="modal-body"><div className="client-detail-top"><span className={`client-avatar avatar-${detail.color}`}>{initials(detail.name)}</span><span className={`status-badge status-${detail.status}`}><i/>{statuses[detail.status]}</span></div><dl className="detail-list"><div><dt>Электронная почта</dt><dd>{detail.email}</dd></div><div><dt>Компания</dt><dd>{detail.company}</dd></div><div><dt>Тариф</dt><dd>{detail.plan}</dd></div><div><dt>Выручка</dt><dd>{money(detail.revenue)}</dd></div><div><dt>Дата добавления</dt><dd>{dateLabel(detail.date)}</dd></div></dl><div className="detail-actions"><Button size="l" view="outlined" onClick={()=>exportCsv([detail])}><Icon name="download" size={16}/>Экспорт</Button><Button size="l" className="primary-button" onClick={()=>updateStatus(new Set([detail.id]),detail.status==='"'archived'?'active':'archived')}><Icon name={detail.status==='archived'?'check':'archive'} size={16}/>{detail.status==='archived'?'Восстановить':'В архив'}</Button></div></div></>}</Modal>
